<script setup>
import { computed } from 'vue'
import { useAuthStore } from '../stores/auth'
import { useSchoolStore } from '../stores/school'
import { marks } from '../data/seed'
import StatCard from '../components/StatCard.vue'
import PerformanceChart from '../components/PerformanceChart.vue'

const auth = useAuthStore()
const school = useSchoolStore()
const user = computed(() => auth.user)
const isParent = computed(() => user.value?.role === 'parent')
const isTeacher = computed(() => user.value?.role === 'teacher')
const greeting = computed(() => new Date().getHours() < 12 ? 'Good morning' : new Date().getHours() < 18 ? 'Good afternoon' : 'Good evening')
const students = computed(() => isParent.value ? school.myChildren : school.students)
</script>
<template>
  <div class="welcome-row"><div><div class="date-label">MONDAY, MAY 12, 2025 <span>✦</span></div><h1>{{ greeting }}, {{ user?.name.split(' ')[0] }} <span>✦</span></h1><p>{{ isParent ? 'Here’s how Ava is doing this term.' : isTeacher ? 'Here’s what’s happening with your class today.' : 'Here’s what’s happening across your school today.' }}</p></div><button v-if="!isParent" class="outline-button" @click="$router.push(isTeacher ? '/attendance' : '/students')"><span>＋</span> {{ isTeacher ? 'Take attendance' : 'Add student' }}</button><button v-else class="outline-button" @click="$router.push('/parent')">View full report <span>→</span></button></div>
  <div v-if="!isParent" class="stat-grid"><StatCard label="Total students" :value="String(school.students.length).padStart(2, '0')" change="8.2%" note="vs last term" icon="♙" tone="icon-lavender"/><StatCard label="Attendance rate" value="94.6%" change="2.4%" note="vs last month" icon="◷" tone="icon-mint"/><StatCard label="Average score" value="86.2%" change="4.1%" note="vs last term" icon="▤" tone="icon-peach"/><StatCard label="Needs attention" value="03" change="2 students" note="improved this week" icon="♡" tone="icon-sky"/></div>
  <div v-else class="stat-grid"><StatCard label="Attendance" value="96%" change="2.4%" note="vs last term" icon="◷" tone="icon-mint"/><StatCard label="Average score" value="91.0%" change="4.1%" note="vs last term" icon="▤" tone="icon-lavender"/><StatCard label="Subjects on track" value="5 of 5" change="All subjects" note="looking great" icon="✦" tone="icon-peach"/></div>
  <div class="dashboard-grid"><section class="panel performance-panel"><div class="panel-heading"><div><h2>{{ isParent ? 'Ava’s academic progress' : 'Academic performance' }}</h2><p>{{ isParent ? 'Steady growth across all subjects' : 'School-wide student performance over time' }}</p></div><button class="select-pill">This academic year <span>⌄</span></button></div><div class="chart-legend"><span><i></i> Average score</span><span><i></i> School target</span></div><PerformanceChart /></section><section class="panel attendance-panel"><div class="panel-heading"><div><h2>Attendance</h2><p>Attendance summary this month</p></div><button class="more-button">···</button></div><div class="attendance-ring"><div><strong>{{ isParent ? '96%' : '94.6%' }}</strong><span>Average<br/>attendance</span></div><svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="65" class="ring-track"/><circle cx="80" cy="80" r="65" class="ring-progress"/></svg></div><div class="attendance-key"><span><i class="present-dot"></i> Present <strong>{{ isParent ? '96%' : '94.6%' }}</strong></span><span><i class="absent-dot"></i> Absent <strong>{{ isParent ? '4%' : '5.4%' }}</strong></span></div><RouterLink :to="isParent ? '/parent' : '/attendance'" class="text-link">View attendance report <span>→</span></RouterLink></section></div>
  <div class="lower-grid"><section class="panel students-panel"><div class="panel-heading"><div><h2>{{ isParent ? 'Subject performance' : 'Recent students' }}</h2><p>{{ isParent ? 'Ava’s results from the latest assessment' : 'Keep an eye on your students’ progress' }}</p></div><RouterLink v-if="!isParent" to="/students" class="text-link">View all <span>→</span></RouterLink><RouterLink v-else to="/parent" class="text-link">See results <span>→</span></RouterLink></div><div v-if="isParent" class="subject-list"><div v-for="subject in marks" :key="subject.subject" class="subject-row"><span class="subject-color" :style="{ background: subject.color }"></span><strong>{{ subject.subject }}</strong><div class="subject-bar"><i :style="{ width: `${subject.score}%`, background: subject.color }"></i></div><b>{{ subject.score }}%</b><span class="grade-pill">{{ subject.grade }}</span></div></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>STUDENT</th><th>CLASS</th><th>ATTENDANCE</th><th>AVG. SCORE</th><th>STATUS</th></tr></thead><tbody><tr v-for="student in students.slice(0, 5)" :key="student.id"><td><div class="person-cell"><span class="avatar" :class="`avatar-${student.color}`">{{ student.initials }}</span><span><strong>{{ student.name }}</strong><small>{{ student.id }}</small></span></div></td><td>{{ student.className }} · {{ student.section }}</td><td><span class="attendance-number">{{ student.attendance }}%</span></td><td><strong class="score-number">{{ student.average }}%</strong></td><td><span class="status-pill" :class="statusClass(student.status)">{{ student.status }}</span></td></tr></tbody></table></div></section><section class="panel updates-panel"><div class="panel-heading"><div><h2>Recent updates</h2><p>Latest activity across the school</p></div><button class="more-button">···</button></div><div class="updates-list"><div class="update-item"><span class="update-icon update-lavender">▤</span><div><strong>Mid-term results published</strong><p>Grade 8 results are now available</p><small>2 hours ago</small></div><span class="update-arrow">↗</span></div><div class="update-item"><span class="update-icon update-mint">◷</span><div><strong>Attendance report ready</strong><p>April attendance summary</p><small>Yesterday</small></div><span class="update-arrow">↗</span></div><div class="update-item"><span class="update-icon update-peach">♙</span><div><strong>New student enrolled</strong><p>Welcome to the MeStar family!</p><small>May 9, 2025</small></div><span class="update-arrow">↗</span></div></div><a class="text-link updates-link" href="#updates">View all activity <span>→</span></a></section></div>
</template>
<script>
export default { methods: { statusClass(status) { return status === 'Excellent' ? 'status-green' : status === 'Needs support' ? 'status-amber' : 'status-blue' } } }
</script>
